import{z as l,x as s,o as A,c as d,q as n,j as o,D as B,d as a,s as i,S as t,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"行为资产定价的深化","description":"","frontmatter":{"title":"行为资产定价的深化","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/apt-behavioral-deep.md","filePath":"econ/apt-behavioral-deep.md","lastUpdated":1791063341000}'),p={name:"econ/apt-behavioral-deep.md"};function F(m,E,h,c,D,C){const r=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=n('<h1 id="行为资产定价的深化" tabindex="-1">行为资产定价的深化 <a class="header-anchor" href="#行为资产定价的深化" aria-label="Permalink to &quot;行为资产定价的深化&quot;">​</a></h1><div class="epigraph"><p>当弯曲不能全推给外生状态，就把弯曲者从状态搬进主体：偏好、信念、套利者的资产负债表，三处都能动手术——但每一处都欠一笔证据。</p><footer>—— 据 Campbell and Cochrane, *JPE* 1999；Barberis, Huang and Santos, *Econometrica* 2001；De Long et al., *JPE* 1990 整理</footer></div><p><a href="/econ/apt-tail-risk-premia">上一课</a>在保持理性与期望效用的前提下，把左尾装进核的弯曲。缺口是：如果弯曲的根源不在状态而在主体——偏好违反期望效用公理、信念系统性偏离贝叶斯、纠正错价本身有风险——定价的语法要怎么改？本课把三个手术台摆在一起，讲各自怎么改、改出什么可检验含义、各欠哪笔证据。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>理性框架留下三个残余反常。溢价对风险厌恶的要求仍然偏高，即便装了灾难；预期数据与实现收益方向相反——投资者在市场涨后更乐观，随后收益却更低（Greenwood–Shleifer 2014 的证据，见<a href="/econ/survey-expectations">调查预期</a>）；价格对红利的反应超过现值模型允许的幅度（<a href="/econ/shiller-excess-volatility">Shiller 过度波动</a>）。三个反常共享一问：核的时变弯曲从哪里来。把它继续归给外生状态，候选状态越列越多，越像补丁。</p><p><span class="marginnote">Barberis–Huang–Santos 2001 把 Kahneman–Tversky 的损失厌恶系数 λ≈2.25 引入消费资产定价，并让参照点随上一期盈亏移动：账面亏损后投资者更怕再亏，风险厌恶升高——弯曲不再需要灾难状态，账面盈亏本身就是状态变量。</span></p><p><span class="marginnote">「核的弯曲」翻译成白话：把未来的钱折算到今天的「汇率」不是常数——坏时候一元更值钱，好时候一元更不值钱。理性模型让这个汇率只随外生状态（衰退、灾难）弯；行为模型说，它还会随人的心情（参照点）、想法（信念偏差）、钱包（套利者资金）而弯。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三个手术台，各动一处。偏好侧：习惯形成让风险厌恶随剩余消费比率时变（Campbell–Cochrane 1999，见<a href="/econ/habit-formation">习惯形成</a>）；损失厌恶把价值函数钉在参照点上并随前次盈亏移动（<a href="/econ/prospect-theory-asset-pricing">前景理论资产定价</a>）；模糊厌恶连概率测度一起换（<a href="/econ/ellsberg-ambiguity">Ellsberg 模糊</a>、<a href="/econ/maxmin-eu">maxmin 期望效用</a>）。信念侧：对信号精度的过度自信（<a href="/econ/dhs-overconfidence">DHS 过度自信</a>）、保守性与代表性（<a href="/econ/bsv-sentiment-model">BSV 情绪模型</a>）、诊断性预期（<a href="/econ/diagnostic-expectations">诊断性预期</a>）分别改写贝叶斯更新的不同环节。套利侧：即便价格错了，纠正它要先承担让它更错的风险——<a href="/econ/noise-trader-risk">噪声交易者风险</a>（De Long–Shleifer–Summers–Waldmann 1990）与<a href="/econ/limits-to-arbitrage">套利限制</a>（Shleifer–Vishny 1997）给出偏离在均衡里存活的资金条件。第三课的异质信念是信念侧不需要偏差的特例：那里只需分散，这里连贝叶斯也可以不要。</p>',9)),(A(),o(t,null,{default:B(()=>[i(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PREF%5B%22%E5%81%8F%E5%A5%BD%E5%BC%AF%E6%9B%B2%3A%20%E4%B9%A0%E6%83%AF%20%2F%20%E6%8D%9F%E5%A4%B1%E5%8E%8C%E6%81%B6%20%2F%20%E6%A8%A1%E7%B3%8A%22%5D%20--%3E%20BEND%5B%22%E6%A0%B8%E7%9A%84%E6%97%B6%E5%8F%98%E5%BC%AF%E6%9B%B2%22%5D%0A%20%20BEL%5B%22%E4%BF%A1%E5%BF%B5%E5%BC%AF%E6%9B%B2%3A%20%E8%BF%87%E5%BA%A6%E8%87%AA%E4%BF%A1%20%2F%20%E8%AF%8A%E6%96%AD%E6%80%A7%22%5D%20--%3E%20BEND%0A%20%20ARB%5B%22%E5%A5%97%E5%88%A9%E9%99%90%E5%88%B6%3A%20%E5%99%AA%E5%A3%B0%E4%BA%A4%E6%98%93%E8%80%85%E9%A3%8E%E9%99%A9%22%5D%20--%3E%20SURV%5B%22%E5%81%8F%E7%A6%BB%E5%9C%A8%E5%9D%87%E8%A1%A1%E4%B8%AD%E5%AD%98%E6%B4%BB%22%5D%0A%20%20BEND%20--%3E%20EVID%5B%22%E5%90%84%E8%87%AA%E8%AF%81%E6%8D%AE%E4%B9%89%E5%8A%A1%3A%20%E6%B6%88%E8%B4%B9%20%2F%20%E9%A2%84%E6%9C%9F%E6%95%B0%E6%8D%AE%20%2F%20%E4%B8%AD%E4%BB%8B%E8%B4%9F%E5%80%BA%E8%A1%A8%22%5D%0A%20%20SURV%20--%3E%20EVID%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("三条路在核的语法里同构：都是让弯曲时变化、并对齐到坏时点——习惯在衰退时弯曲，损失厌恶在亏损后弯曲，噪声交易者风险在套利者被挤出时弯曲。区别在证据义务：偏好模型要过第二课的界并核对消费动态；信念模型要过预期数据——调查测得的预期与随后收益的对照；套利模型要报套利者的资产负债表与资金成本。处置效应（"),e("a",{href:"/econ/disposition-effect"},"处置效应"),a("）是损失厌恶留在交易记录里的指纹，把实验参数与市场行为接起来。机制上最要紧的一点：套利限制不是理论豁免，而是均衡条件——偏离能存活，是因为消除它的交易有风险有成本，这句话本身必须被数据支持。")],-1)),E[5]||(E[5]=e("p",null,"上一张图并列了三个手术台；这一张回答另一个问题：拿到一份市场数据，怎么按证据义务把三条路逐一排查——这正是「判别要靠第三类证据」的操作化。",-1)),(A(),o(t,null,{default:B(()=>[i(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20PZ%5B%22%E8%A7%82%E5%AF%9F%E5%88%B0%E6%BA%A2%E4%BB%B7%E5%81%8F%E9%AB%98%E6%88%96%E9%94%99%E4%BB%B7%E9%95%BF%E6%9C%9F%E5%AD%98%E6%B4%BB%22%5D%20--%3E%20Q1%7B%22%E6%B6%88%E8%B4%B9%E5%8A%A8%E6%80%81%E8%83%BD%E8%A7%A3%E9%87%8A%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%22%E8%83%BD%EF%BC%8C%E4%B8%94%E6%97%B6%E5%8F%98%E5%AF%B9%E9%BD%90%E5%9D%8F%E6%97%B6%E7%82%B9%22%7C%20HAB%5B%22%E5%81%8F%E5%A5%BD%E4%BE%A7%EF%BC%9A%E4%B9%A0%E6%83%AF%20%2F%20%E6%8D%9F%E5%A4%B1%E5%8E%8C%E6%81%B6%22%5D%0A%20%20Q1%20--%3E%7C%22%E4%B8%8D%E8%83%BD%22%7C%20Q2%7B%22%E8%B0%83%E6%9F%A5%E9%A2%84%E6%9C%9F%E4%B8%8E%E9%9A%8F%E5%90%8E%E6%94%B6%E7%9B%8A%E6%96%B9%E5%90%91%E4%B8%80%E8%87%B4%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%22%E9%A2%84%E6%9C%9F%E6%9B%B4%E4%B9%90%E8%A7%82%EF%BC%8C%E6%94%B6%E7%9B%8A%E5%8F%8D%E8%80%8C%E6%9B%B4%E4%BD%8E%22%7C%20BEL%5B%22%E4%BF%A1%E5%BF%B5%E4%BE%A7%EF%BC%9A%E8%BF%87%E5%BA%A6%E8%87%AA%E4%BF%A1%20%2F%20%E8%AF%8A%E6%96%AD%E6%80%A7%E9%A2%84%E6%9C%9F%22%5D%0A%20%20Q2%20--%3E%7C%22%E9%A2%84%E6%9C%9F%E6%B2%A1%E7%B3%BB%E7%BB%9F%E6%80%A7%E5%81%8F%E5%B7%AE%22%7C%20Q3%7B%22%E9%94%99%E4%BB%B7%E4%B8%BA%E4%BD%95%E6%B2%A1%E8%A2%AB%E7%BA%A0%E6%AD%A3%EF%BC%9F%22%7D%0A%20%20Q3%20--%3E%7C%22%E5%A5%97%E5%88%A9%E8%80%85%E8%B4%9F%E5%80%BA%E8%A1%A8%E4%B8%8E%E8%B5%84%E9%87%91%E5%8F%97%E9%99%90%22%7C%20ARB%5B%22%E5%A5%97%E5%88%A9%E4%BE%A7%EF%BC%9A%E5%99%AA%E5%A3%B0%E4%BA%A4%E6%98%93%E8%80%85%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=n('<p><span class="marginnote">数字实例：λ≈2.25 意味着亏 1 万元带来的痛苦约等于赚 2.25 万元带来的快乐。于是账户浮亏后，同样波动的股票在心里显得「更危险」，必须给出更高的期望补偿投资者才肯继续持有——这是「账面亏损后溢价升高」最直接的微观来源。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>行为建模的代价是可证伪性弱：偏差清单开放，「一个偏差救一个异常」的补丁式结构难以整体否证。实验校准的参数（λ≈2.25）搬进市场要跨场景保持，这一步常常没有检验。与理性模型的区分在数据上困难：习惯与长期风险、灾难与诊断性预期，可预测性预言常常相似，判别要靠第三类证据（预期数据、微观账户、中介头寸），而这正是下一课的流水线要处理的事。不要把行为当成免检标签：改了偏好或信念，第二课的界一寸不让。</p><p><span class="marginnote">常见误区：初学者容易以为「行为金融 = 推翻理性定价」。实际上本课的纪律恰好相反——无论怎么改偏好或信念，无套利与欧拉方程的约束一寸不让；行为只是给「弯曲从哪里来」换了一批候选来源，可证伪的要求反而更严。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三个手术台：偏好弯曲、信念弯曲、套利限制；前两者改核，第三个解释偏离为何存活。</li><li>三条路同构——让弯曲时变并对齐坏时点；区别在各自欠的证据义务。</li><li>损失厌恶的 λ≈2.25 加参照点移动，让账面盈亏成为状态变量，是行为侧最紧凑的定价机制。</li><li>行为不是免检标签：界照常适用，判别要靠第三类证据而非拟合优度。</li><li>出处：Campbell and Cochrane, <em>JPE</em> 1999；Barberis, Huang and Santos, <em>Econometrica</em> 2001；De Long, Shleifer, Summers and Waldmann, <em>JPE</em> 1990；Shleifer and Vishny, <em>JF</em> 1997。</li></ul>',6))])}const b=l(p,[["render",F]]);export{u as __pageData,b as default};
